-- Run AFTER schema.sql. The PERSISTENT template library Claude reads from.
-- 'Save to library' in the app writes here; one-off tasks stay only on their event.
create table if not exists library_tasks (
  id uuid primary key default gen_random_uuid(),
  workstream text not null,        -- workstream / activation it belongs to
  timing text,
  title text not null,
  owner text,
  applies_to text,
  notes text,
  created_at timestamptz default now(),
  unique (workstream, title)
);
alter table library_tasks disable row level security;   -- prototype only

-- Seed the library with the current 858 template (so it starts full).
